<?php
namespace Core;require_once __DIR__.'/Guard.php';ml_guard_shield(__FILE__);class Cache{private static $redis=null;private static $mem=null;private static $useApCu=false;private static $inited=false;private static $backend='file';public static function init(){if(self::$inited){return;}self::$inited=true;try{$a=Config::sub('cache','redis',array());if(!empty($a['host'])&&class_exists('\\Redis')){self::$redis=new \Redis();self::$redis->connect($a['host'],isset($a['port'])?(int)$a['port']:6379,1.0);if(!empty($a['auth'])){self::$redis->auth($a['auth']);}if(!empty($a['db'])){self::$redis->select((int)$a['db']);}self::$backend='redis';return;}}catch(\Throwable $b){}try{$c=Config::sub('cache','memcached',array());if(!empty($c['host'])&&class_exists('\\Memcached')){self::$mem=new \Memcached('ml-cache');self::$mem->addServer($c['host'],isset($c['port'])?(int)$c['port']:11211,100);self::$backend='memcached';return;}}catch(\Throwable $b){}if(function_exists('apcu_fetch')&&@apcu_enabled()){self::$useApCu=true;self::$backend='apcu';return;}self::$backend='file';}public static function backend(){self::init();return self::$backend;}private static function k($a){return'ml:'.substr(hash('sha256',(string)$a),0,32);}public static function get($a){self::init();try{if(self::$backend==='redis'&&self::$redis){$b=self::$redis->get(self::k($a));return($b===false)?false:unserialize($b);}if(self::$backend==='memcached'&&self::$mem){$b=self::$mem->get(self::k($a));return($b===false)?false:$b;}if(self::$useApCu){$c=false;$b=apcu_fetch(self::k($a),$c);return $c?$b:false;}return self::fileGet($a);}catch(\Throwable $d){return false;}}public static function set($a,$b,$c=300){self::init();try{if(self::$backend==='redis'&&self::$redis){$d=serialize($b);if($c<=0){return(bool)self::$redis->set(self::k($a),$d);}return(bool)self::$redis->setex(self::k($a),$c,$d);}if(self::$backend==='memcached'&&self::$mem){return(bool)self::$mem->set(self::k($a),$b,max(1,(int)$c));}if(self::$useApCu){return apcu_store(self::k($a),$b,max(1,(int)$c));}return self::fileSet($a,$b,$c);}catch(\Throwable $f){return false;}}public static function delete($a){self::init();try{if(self::$backend==='redis'&&self::$redis){self::$redis->del(self::k($a));return true;}if(self::$backend==='memcached'&&self::$mem){return(bool)self::$mem->delete(self::k($a));}if(self::$useApCu){return apcu_delete(self::k($a));}return self::fileDelete($a);}catch(\Throwable $b){return false;}}public static function invalidatePrefix($a){self::init();$b=dirname(__DIR__).'/cache';if(!is_dir($b)){return 0;}$c=0;foreach(glob($b.'/'.$a.'*')as $d){if(@unlink($d)){$c++;}}if(self::$backend==='redis'&&self::$redis){$e=null;do{$f=self::$redis->scan($e,'ml:*',100);if(!is_array($f)||count($f)===0){break;}list($e,$g)=$f;foreach($g as $h){if(strpos($h,'ml:')===0){self::$redis->del($h);$c++;}}}while($e!==null&&$e!==0);}return $c;}public static function flush(){self::init();try{if(self::$backend==='redis'&&self::$redis){self::$redis->flushDB();return true;}if(self::$backend==='memcached'&&self::$mem){return(bool)self::$mem->flush();}if(self::$useApCu){return apcu_clear_cache();}$a=dirname(__DIR__).'/cache';if(!is_dir($a)){return false;}$b=0;foreach(glob($a.'/*')as $c){if(is_file($c)&&@unlink($c)){$b++;}}return $b>0;}catch(\Throwable $d){return false;}}public static function stats(){self::init();if(self::$backend==='redis'&&self::$redis){return array('backend'=>'redis','memory'=>self::$redis->info('memory'),'stats'=>self::$redis->info('stats'),);}if(self::$backend==='apcu'){return array('backend'=>'apcu','stats'=>apcu_cache_info(true),);}return array('backend'=>self::$backend,);}private static function fileGet($a){$b=self::file($a);if(!is_file($b)){return false;}$c=@file_get_contents($b);if($c===false){return false;}$d=strpos($c,"\n");if($d===false){return false;}if(strncmp($c,'E:',2)!==0){return false;}$e=(int)substr($c,2,$d-2);$f=time()-(int)@filemtime($b);if($f>$e){@unlink($b);return false;}$g=substr($c,$d+1);if(strncmp($g,'J:',2)!==0){return false;}return json_decode(substr($g,2),true);}private static function fileSet($a,$b,$c){$d=self::file($a);$e=json_encode($b,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);if($e===false){return false;}$f=dirname($d);if(!is_dir($f)){@mkdir($f,0750,true);}$g='E:'.(int)$c."\n".'J:'.$e;$h=$d.'.'.getmypid().'.'.bin2hex(random_bytes(4)).'.tmp';if(@file_put_contents($h,$g,LOCK_EX)===false){return false;}if(!@rename($h,$d)){@unlink($h);return false;}return true;}private static function fileDelete($a){$b=self::file($a);return@unlink($b)||!is_file($b);}private static function file($a){$b=substr(hash('sha256',(string)$a),0,32);return dirname(__DIR__).'/cache/'.$b.'.cache';}}